const NL = String.fromCharCode(10);
const inputData = $input.first().json || {};
const isManualTest =
  Object.keys(inputData).length === 0 ||
  (!inputData.body && !inputData.payload && !inputData.event);

const root = inputData.body || inputData || {};
const payload = root.payload || root.data || root || {};
const eventName = String(root.event || '').toLowerCase();
const isAllowedEvent =
  isManualTest || !eventName || eventName === 'message' || eventName === 'message.any';

const fromMe = isManualTest ? false : Boolean(payload.fromMe);
const rawFrom = isManualTest
  ? '<GANTI_WA_ADMIN_CHAT_ID>'
  : String(payload.from || payload.chatId || '');

const rawText = isManualTest
  ? String(
      inputData.testPrompt ||
        'Halo Transkep AI! Konfirmasi singkat bahwa Workflow Transkep AI Assistant sudah aktif dan siap melayani.'
    ).trim()
  : String(
      payload.body ||
        payload.text ||
        (payload.message &&
          (payload.message.conversation ||
            (payload.message.extendedTextMessage && payload.message.extendedTextMessage.text))) ||
        (payload._data &&
          (payload._data.body || (payload._data.Message && payload._data.Message.conversation))) ||
        ''
    ).trim();

const messageId = String(payload.id || '');
const rawJsonStr = JSON.stringify(root);
const notifyName = String(
  (payload._data && (payload._data.notifyName || payload._data.pushname)) ||
    payload.notifyName ||
    ''
).toLowerCase();

const isBotSelf = rawFrom.includes('<GANTI_NO_WA_BOT>');
const isGroupOrBroadcast =
  rawFrom === '' ||
  rawFrom.includes('@g.us') ||
  rawFrom.includes('status@broadcast') ||
  rawFrom.includes('@newsletter');

const hasAdminNumber = rawJsonStr.includes('<GANTI_NO_WA_ADMIN_TANPA_NOL>');
const hasAdminName = notifyName.includes('dedi') || notifyName.includes('sopiyan');
const isLidPrivate = rawFrom.endsWith('@lid');

const isAuthorized =
  isManualTest ||
  (isAllowedEvent &&
    !fromMe &&
    !isBotSelf &&
    !isGroupOrBroadcast &&
    rawText.length > 0 &&
    (hasAdminNumber || hasAdminName || isLidPrivate));

const replyChatId = rawFrom.endsWith('@c.us') ? rawFrom : '<GANTI_WA_ADMIN_CHAT_ID>';
const waktuWIB = new Intl.DateTimeFormat('id-ID', {
  timeZone: 'Asia/Jakarta',
  dateStyle: 'full',
  timeStyle: 'long',
}).format(new Date());

let staticData = {};
try {
  if (typeof $getWorkflowStaticData === 'function') {
    staticData = $getWorkflowStaticData('global') || {};
  }
} catch (e) {
  staticData = {};
}
let chatEpoch = Number(staticData.chatEpoch || 1);

const lowerText = rawText.toLowerCase().trim();
let routeType = 'ai_chat';
let quickAction = '';
let wantsAiDockerAnalysis = false;
let modeLabel = '🤖 Transkep AI Partner';
let cleanPrompt = rawText;
let systemPersona = '';

const isResetCmd =
  /^(?:\/|!)?(?:reset|clear|hapusmemori|reset chat|reset memori|clear chat)$/i.test(lowerText);
const isMenuCmd =
  /^(?:\/|!)?(?:menu|help|bantuan|perintah|panduan)$/i.test(lowerText);

const hasDockerSlash =
  /^\/(?:server|status|docker|kontainer|ps)\b|^!(?:server|status|docker|kontainer|ps)\b|^\/(?:analisa|analisis|diagnosa)\s+docker\b/i.test(
    lowerText
  );
const mentionsDockerTarget = /\b(?:docker|kontainer|container)\b/i.test(lowerText);
const hasDockerQueryVerb =
  /\b(?:jalan|berjalan|running|aktif|nyala|hidup|mati|stop|stopped|exited|down|status|cek|lihat|daftar|list|apa saja|apa aja|laporan|info|pantau|kondisi|kesehatan|health|sehat|crash|restart|error|masalah|bermasalah|kenapa|analisa|analisis|diagnosa|ram|cpu|memori|memory|resource|uptime|port|ps|stats)\b/i.test(
    lowerText
  );
const isConceptualDockerQuestion =
  !hasDockerSlash &&
  /\b(?:pengertian|definisi|kelebihan|kekurangan|fungsi|sejarah|tutorial|cara install|belajar|contoh dockerfile|perbedaan)\b/i.test(
    lowerText
  );
const isDockerIntent =
  hasDockerSlash || (!isConceptualDockerQuestion && mentionsDockerTarget && hasDockerQueryVerb);

const skMatch = rawText.match(/^\/sk(?:\s+([\s\S]+))?$/i);
const sopMatch = rawText.match(/^\/sop(?:\s+([\s\S]+))?$/i);
const notulenMatch = rawText.match(/^\/notulen(?:\s+([\s\S]+))?$/i);

if (isAuthorized && isResetCmd) {
  chatEpoch += 1;
  staticData.chatEpoch = chatEpoch;
  routeType = 'quick_reply';
  quickAction = 'reset';
  modeLabel = '🔄 Transkep AI Memory Reset';
} else if (isMenuCmd) {
  routeType = 'quick_reply';
  quickAction = 'menu';
  modeLabel = '🧭 Panduan Transkep AI Assistant';
} else if (isDockerIntent) {
  routeType = 'docker';
  const hasSlashWithArgs =
    /^\/(?:server|status|docker|kontainer|ps)\s+\S+/i.test(lowerText) ||
    /^!(?:server|status|docker|kontainer|ps)\s+\S+/i.test(lowerText);
  const hasAiAnalysisCue =
    /^\/(?:analisa|analisis|diagnosa)\b/i.test(lowerText) ||
    /\b(?:analisa|analisis|diagnosa|kenapa|mengapa|penyebab|solusi|rekomendasi|saran|jelaskan|evaluasi|troubleshooting|troubleshoot|perbaiki)\b/i.test(
      lowerText
    );
  wantsAiDockerAnalysis = hasSlashWithArgs || hasAiAnalysisCue;
  modeLabel = wantsAiDockerAnalysis
    ? '🐳🔬 Transkep AI — Analisa Docker Server'
    : '🐳 Status Kontainer Docker Transkep';
} else if (skMatch) {
  cleanPrompt =
    (skMatch[1] && skMatch[1].trim()) ||
    'Jelaskan cara menggunakan perintah /sk beserta contoh draf Surat Keputusan (SK) resmi.';
  modeLabel = '📜 Transkep AI — Pakar SK & Regulasi MA-RI';
  systemPersona =
    'Kamu adalah Transkep AI (asisten resmi ekosistem TRANSKEP), Pakar Hukum dan Administrasi Surat Keputusan (SK) Pengadilan Agama Indramayu (Mahkamah Agung RI). Tugasmu membantu Admin Transkep menyusun draf SK (Menimbang, Mengingat, Memutuskan, Menetapkan), menganalisis regulasi kepegawaian ASN/PPPK, KNP, KGB, dan mutasi dengan bahasa hukum tata naskah dinas MA-RI yang presisi.';
} else if (sopMatch) {
  cleanPrompt =
    (sopMatch[1] && sopMatch[1].trim()) ||
    'Jelaskan cara menggunakan perintah /sop beserta struktur Standar Operasional Prosedur (SOP) peradilan.';
  modeLabel = '📋 Transkep AI — Pakar SOP Peradilan';
  systemPersona =
    'Kamu adalah Transkep AI (asisten resmi ekosistem TRANSKEP), Arsitek Standar Operasional Prosedur (SOP) Pengadilan Agama Indramayu. Tugasmu menyusun alur SOP Kepaniteraan, Kesekretariatan, PTSP, dan e-Court lengkap dengan Dasar Hukum, Kualifikasi Pelaksana, Keterkaitan, Peralatan, Waktu Penyelesaian, dan Output yang terukur.';
} else if (notulenMatch) {
  cleanPrompt =
    (notulenMatch[1] && notulenMatch[1].trim()) ||
    'Jelaskan cara menggunakan perintah /notulen untuk merapikan catatan rapat menjadi notulen resmi.';
  modeLabel = '🎙️ Transkep AI — Notulis Eksekutif PA Indramayu';
  systemPersona =
    'Kamu adalah Transkep AI (asisten resmi ekosistem TRANSKEP), Notulis Rapat Eksekutif Pengadilan Agama Indramayu. Tugasmu mengubah catatan rapat mentah menjadi dokumen Notulen Rapat Resmi yang rapi, berisi: 1. Identitas/Agenda Rapat, 2. Pokok Pembahasan, 3. Kesimpulan/Keputusan, dan 4. Rencana Tindak Lanjut (Action Items & PIC).';
} else {
  modeLabel = '🤖 Transkep AI Partner';
  systemPersona =
    'Kamu adalah Transkep AI, asisten pribadi AI resmi ekosistem TRANSKEP dan Technical Partner khusus untuk Admin Transkep (IT & Kepegawaian Pengadilan Agama Indramayu). IDENTITAS WAJIB: selalu perkenalkan dan sebut dirimu hanya sebagai Transkep AI (jangan gunakan nama asisten lain selain Transkep AI). Jawablah dengan cerdas, strategis, solutif, akrab (sapa Bro), serta terstruktur rapi untuk dibaca di WhatsApp. Catatan kemampuan: jika pengguna menanyakan daftar/status kontainer Docker real-time, arahkan mereka memakai /docker atau langsung menanyakan kontainer apa saja yang berjalan di Docker karena obrolan umum tidak mengeksekusi SSH secara langsung.';
}

const fullSystemPrompt =
  systemPersona +
  NL +
  NL +
  '[INFORMASI WAKTU REAL-TIME: ' +
  waktuWIB +
  ']' +
  NL +
  'ATURAN IDENTITAS: Namamu adalah Transkep AI. Gunakan brand Transkep pada setiap identitas jawaban.' +
  NL +
  'ATURAN FORMAT WHATSAPP: Gunakan satu tanda bintang *teks* untuk huruf tebal (JANGAN gunakan dua bintang **teks**). Gunakan poin-poin rapi dan emoji secukupnya agar nyaman dibaca di HP.';

const sessionId = 'transkep_ai_session_e' + chatEpoch;

return [
  {
    json: {
      isAuthorized,
      routeType,
      quickAction,
      wantsAiDockerAnalysis,
      modeLabel,
      rawFrom,
      replyChatId,
      messageId,
      rawText,
      cleanPrompt,
      fullSystemPrompt,
      waktuWIB,
      sessionId,
      chatEpoch,
    },
  },
];

const meta = $('Context & Router Transkep (Code)').first().json || {};
return [
  {
    json: {
      cleanPrompt: String(meta.cleanPrompt || meta.rawText || ''),
      fullSystemPrompt: String(meta.fullSystemPrompt || ''),
      sessionId: String(meta.sessionId || 'transkep_ai_session_e1'),
      modeLabel: String(meta.modeLabel || '🤖 Transkep AI Partner'),
      replyChatId: String(meta.replyChatId || ''),
    },
  },
];

const NL = String.fromCharCode(10);
const sshItem = $input.first().json || {};
const meta = $('Context & Router Transkep (Code)').first().json || {};

function cleanLine(s) {
  return String(s || '').trim().replace(/^"+|"+$/g, '').trim();
}

function compactPorts(rawPorts) {
  const txt = cleanLine(rawPorts);
  if (!txt) return '-';
  const parts = txt.split(',').map((p) => p.trim()).filter(Boolean);
  const uniq = [];
  for (const p of parts) {
    const normalized = p.replace(/^\[::\]:/, '').replace(/^0\.0\.0\.0:/, '');
    if (!uniq.includes(normalized)) uniq.push(normalized);
  }
  return uniq.slice(0, 4).join(', ') + (uniq.length > 4 ? ' (+' + (uniq.length - 4) + ' lainnya)' : '');
}

function parseDockerOutput(item) {
  const errObj = item.error;
  const errMsg = errObj ? String(errObj.message || errObj) : (item.message ? String(item.message) : '');
  const exitCode = item.code !== undefined && item.code !== null ? Number(item.code) : 0;
  const stdout = String(item.stdout || '').trim();
  const stderr = String(item.stderr || '').trim();

  if (!stdout && (errMsg || stderr || exitCode !== 0)) {
    return {
      ok: false,
      errorText: errMsg || stderr || ('SSH exit code ' + exitCode),
      running: [],
      stopped: [],
      rawFallback: '',
    };
  }

  const lines = stdout.split(/\r?\n/).map(cleanLine).filter(Boolean);
  const markerIdx = lines.findIndex((l) => l === '---STATS---');
  const psLines = markerIdx >= 0 ? lines.slice(0, markerIdx) : lines;
  const statsLines = markerIdx >= 0 ? lines.slice(markerIdx + 1) : [];

  const statsMap = {};
  for (const sl of statsLines) {
    if (!sl || sl === 'NO_STATS') continue;
    const cols = sl.split('|');
    if (cols.length >= 3) {
      const name = cleanLine(cols[0]);
      statsMap[name] = { cpu: cleanLine(cols[1]) || '-', mem: cleanLine(cols[2]) || '-' };
    }
  }

  const running = [];
  const stopped = [];
  let parsedPipeCount = 0;

  for (const pl of psLines) {
    const cols = pl.split('|');
    if (cols.length >= 4) {
      parsedPipeCount += 1;
      const name = cleanLine(cols[0]);
      const state = cleanLine(cols[1]).toLowerCase();
      const status = cleanLine(cols[2]);
      const image = cleanLine(cols[3]);
      const ports = compactPorts(cols.slice(4).join('|'));
      const stat = statsMap[name] || { cpu: '-', mem: '-' };
      const entry = { name, state, status, image, ports, cpu: stat.cpu, mem: stat.mem };
      if (state === 'running') running.push(entry);
      else stopped.push(entry);
    }
  }

  if (parsedPipeCount === 0 && psLines.length > 0) {
    return { ok: true, running: [], stopped: [], rawFallback: psLines.join(NL) };
  }

  return { ok: true, errorText: '', running, stopped, rawFallback: '' };
}

function buildDockerSummary(parsed) {
  if (!parsed.ok) {
    return (
      '⚠️ *Gagal mengambil data Docker via SSH.*' + NL +
      'Detail: ' + parsed.errorText + NL +
      'Pastikan Docker Desktop / Docker Engine aktif dan service SSH di server berjalan normal.'
    );
  }
  if (parsed.rawFallback) {
    return '🐳 *Output Docker Mentah:*' + NL + parsed.rawFallback;
  }

  const total = parsed.running.length + parsed.stopped.length;
  const out = [];
  out.push(
    '📊 *Ringkasan:* ✅ Berjalan: *' + parsed.running.length + '* | 🔴 Berhenti/Lainnya: *' + parsed.stopped.length + '* | 📦 Total: *' + total + '*'
  );

  if (total === 0) {
    out.push('', 'ℹ️ Tidak ada kontainer Docker yang terdaftar saat ini.');
    return out.join(NL);
  }

  if (parsed.running.length > 0) {
    out.push('', '🟢 *KONTAINER BERJALAN (' + parsed.running.length + '):*');
    for (const c of parsed.running) {
      out.push('• *' + c.name + '* (' + c.status + ')');
      out.push('  ↳ CPU: ' + c.cpu + ' | RAM: ' + c.mem + ' | Image: ' + c.image);
      if (c.ports && c.ports !== '-') {
        out.push('  ↳ Port: ' + c.ports);
      }
    }
  } else {
    out.push('', '🔴 *Tidak ada kontainer Docker yang sedang berjalan!*');
  }

  if (parsed.stopped.length > 0) {
    out.push('', '🔴 *KONTAINER BERHENTI / MASALAH (' + parsed.stopped.length + '):*');
    for (const c of parsed.stopped) {
      out.push('• *' + c.name + '* [' + c.state + '] — ' + c.status + ' (Image: ' + c.image + ')');
    }
  }

  return out.join(NL);
}

const parsed = parseDockerOutput(sshItem);
const summary = buildDockerSummary(parsed);

const cleanPrompt =
  'Permintaan Admin Transkep: "' +
  String(meta.rawText || '/analisa docker') +
  '"' +
  NL +
  NL +
  '=== DATA REAL-TIME KONTAINER DOCKER TRANSKEP (' +
  String(meta.waktuWIB || '-') +
  ') ===' +
  NL +
  summary +
  NL +
  '==============================================================' +
  NL +
  NL +
  'Analisislah data kontainer Docker real-time di atas untuk menjawab permintaan Admin Transkep secara akurat, ringkas, dan solutif. Jangan mengarang kontainer atau angka di luar data SSH di atas.';

const fullSystemPrompt =
  'Kamu adalah Transkep AI, asisten DevOps & Infrastruktur Docker resmi ekosistem TRANSKEP.' +
  NL +
  'Tugasmu menganalisa laporan kontainer Docker real-time (container running, stopped/exited, port, CPU, RAM) dan memberikan insight serta langkah perbaikan praktis dalam Bahasa Indonesia yang akrab (sapa Bro).' +
  NL +
  'ATURAN IDENTITAS: Namamu adalah Transkep AI (jangan gunakan nama asisten lain selain Transkep AI).' +
  NL +
  'ATURAN FORMAT WHATSAPP: Gunakan satu tanda bintang *teks* untuk tebal (JANGAN gunakan **teks**).';

return [
  {
    json: {
      cleanPrompt,
      fullSystemPrompt,
      sessionId: String(meta.sessionId || 'transkep_ai_session_e1'),
      modeLabel: String(meta.modeLabel || '🐳🔬 Transkep AI — Analisa Docker Server'),
      replyChatId: String(meta.replyChatId || ''),
    },
  },
];

