const item = $input.first().json || {};
const errRaw = item.error ? String(item.error.message || item.error) : '';
const errText = errRaw
  ? '⏳ *Kendala Koneksi Google AI:* ' +
    errRaw +
    NL +
    NL +
    '💡 *Tips:* Cek kuota/ketersediaan model di node *Google Gemini Chat Model* (default `models/gemini-3.8-flash`; fallback ringan `models/gemini-3.5-flash-lite`).'
